// 2. Validate Input
// Confirms the alarm from WF-03 has what this workflow needs, above all a
// siteId to look up in the site metadata sheet.

const REQUIRED = ['correlationId', 'siteId', 'alarmType', 'priority'];

const item = $input.first().json;
const missing = REQUIRED.filter((f) => item[f] === undefined || item[f] === null || item[f] === '');

return [{
  json: {
    isValid: missing.length === 0,
    missingFields: missing,
    ...item
  }
}];

// 4. Merge Metadata
// Combines the alarm + AI classification (from WF-03) with the site
// metadata row(s) returned by the Google Sheets lookup (0 rows = not found,
// since Site ID is expected to be unique).
//
// '3. Lookup Site' has alwaysOutputData enabled so a not-found case still
// reaches this node (otherwise n8n skips downstream nodes entirely on 0
// items, making the Is Site Found? / Error Output - Site Not Found path
// unreachable). That means a genuine not-found case arrives here as a
// single synthetic empty item ({}), not zero items -- so isSiteFound is
// based on whether that row actually has data, not on item count alone.

const rows = $input.all();
const alarm = $('2. Validate Input').first().json;
const firstRow = rows.length > 0 ? rows[0].json : {};
const isSiteFound = rows.length > 0 && Object.keys(firstRow).length > 0;
const site = isSiteFound ? firstRow : {};

return [{
  json: {
    // Alarm + AI classification fields, passed through from WF-03
    correlationId: alarm.correlationId,
    vendor: alarm.vendor,
    alarmType: alarm.alarmType,
    originalSeverity: alarm.originalSeverity,
    nodeName: alarm.nodeName,
    siteId: alarm.siteId,
    region: alarm.region,
    timestamp: alarm.timestamp,
    alarmCategory: alarm.alarmCategory,
    rootCause: alarm.rootCause,
    impact: alarm.impact,
    priority: alarm.priority,
    recommendedAction: alarm.recommendedAction,
    estimatedResolution: alarm.estimatedResolution,
    confidence: alarm.confidence,
    fieldEngineer: alarm.fieldEngineer,
    aiCustomerImpact: alarm.customerImpact,
    team: alarm.team,
    prevention: alarm.prevention,
    reviewStatus: alarm.reviewStatus,

    // Site metadata fields, from the Google Sheets lookup
    isSiteFound,
    siteName: site['Site Name'] || null,
    division: site['Division'] || null,
    district: site['District'] || null,
    latitude: site['Latitude'] || null,
    longitude: site['Longitude'] || null,
    nodeType: site['Node Type'] || null,
    customerCount: Number(site['Customer Count']) || 0,
    slaTier: site['SLA Tier'] || 'Silver',
    siteOwner: site['Site Owner'] || null,
    transmissionRegion: site['Transmission Region'] || null,
    engineerName: site['Engineer Name'] || null,
    engineerPhone: site['Engineer Phone'] || null,
    backupEngineer: site['Backup Engineer'] || null,
    nearestPOP: site['Nearest POP'] || null,
    fiberRoute: site['Fiber Route'] || null
  }
}];

// 5. Calculate Customer Impact
// Blends the site's actual customer count + SLA tier with the AI's own
// customerImpact judgment from WF-03, and takes the MORE severe of the two
// so metadata never quietly downgrades what the AI flagged.

const item = $input.first().json;

const IMPACT_RANK = { Low: 1, Medium: 2, High: 3 };
const RANK_TO_IMPACT = { 1: 'Low', 2: 'Medium', 3: 'High' };

function baseImpactFromCount(count) {
  if (count > 1000) return 'High';
  if (count >= 200) return 'Medium';
  return 'Low';
}

let computedImpact = baseImpactFromCount(item.customerCount);

// SLA tier modifier: Gold nudges impact up a level, Bronze nudges it down a level
if (item.slaTier === 'Gold' && IMPACT_RANK[computedImpact] < 3) {
  computedImpact = RANK_TO_IMPACT[IMPACT_RANK[computedImpact] + 1];
}
if (item.slaTier === 'Bronze' && IMPACT_RANK[computedImpact] > 1) {
  computedImpact = RANK_TO_IMPACT[IMPACT_RANK[computedImpact] - 1];
}

const aiImpact = item.aiCustomerImpact || 'Low';
const finalImpact = IMPACT_RANK[aiImpact] >= IMPACT_RANK[computedImpact] ? aiImpact : computedImpact;

return [{
  json: {
    ...item,
    computedCustomerImpact: computedImpact,
    customerImpact: finalImpact,
    customerImpactScore: IMPACT_RANK[finalImpact]
  }
}];

// 6. Calculate Business Priority
// Combines AI priority + final customer impact + SLA tier into one
// weighted business priority (P1-P4) that operations can queue/dispatch on.

const item = $input.first().json;

const PRIORITY_WEIGHT = { Critical: 4, Major: 3, Minor: 2, Warning: 1 };
const IMPACT_WEIGHT = { High: 3, Medium: 2, Low: 1 };
const SLA_WEIGHT = { Gold: 2, Silver: 1, Bronze: 0 };

const priorityWeight = PRIORITY_WEIGHT[item.priority] || 1;
const impactWeight = IMPACT_WEIGHT[item.customerImpact] || 1;
const slaWeight = SLA_WEIGHT[item.slaTier] !== undefined ? SLA_WEIGHT[item.slaTier] : 1;

const score = priorityWeight + impactWeight + slaWeight;

let businessPriority;
if (score >= 8) businessPriority = 'P1 - Urgent';
else if (score >= 6) businessPriority = 'P2 - High';
else if (score >= 4) businessPriority = 'P3 - Normal';
else businessPriority = 'P4 - Low';

return [{
  json: {
    ...item,
    businessPriorityScore: score,
    businessPriority,
    enrichedAt: new Date().toISOString()
  }
}];
